import {esc,icon,badge,btn,title,empty,codeBlock,sourceLinks,kindLabel,exerciseCard} from './ui.js';
import {today} from './dashboard.js';
import {orderedLessons} from './core.js';
import {practiceView,practiceList} from './views-lab.js';
import {extraView} from './views-extra.js';
export const pageNames={today:'Today',roadmap:'Learning path',module:'Learning path',learn:'Lesson',practice:'Practice lab',review:'Review queue',notes:'Mistake notebook',progress:'Your progress',visualizers:'Algorithm studio',interview:'Interview room',career:'Career workspace',settings:'Settings'};
export const lessonDone=(s,id)=>Boolean(s.completedLessons[id]&&!s.completedLessons[id].stale);
export function shell(route,{state,catalog,ui}){
 const active=['module','learn'].includes(route.page)?'roadmap':route.page;
 const nav=(key,label,i)=>`<a class="nav-link ${active===key?'active':''}" href="#${key}" ${active===key?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${key==='review'&&ui.dueCount?`<span class="count">${ui.dueCount}</span>`:''}</a>`;
 return `<aside class="sidebar" id="sidebar" aria-label="Navigasi utama"><a href="#today" class="brand"><span class="brand-mark">d.</span><span>DSA Journey<small>LEARN. TRACE. BUILD.</small></span></a><nav><div class="nav-group"><p class="eyebrow">Your workspace</p>${nav('today','Today','home')}${nav('roadmap','Learning path','map')}${nav('practice','Practice lab','code')}${nav('visualizers','Algorithm studio','play')}</div><div class="nav-group"><p class="eyebrow">Build understanding</p>${nav('review','Review queue','review')}${nav('notes','Mistake notebook','note')}${nav('progress','Your progress','chart')}</div><div class="nav-group"><p class="eyebrow">The next chapter</p>${nav('interview','Interview room','target')}${nav('career','Career workspace','briefcase')}${nav('settings','Settings','settings')}</div></nav><div class="sidebar-bottom"><div class="path-note"><strong>Python + C++</strong>Pahami idenya.<br>Tulis. Uji. Ulangi.</div><div class="sidebar-footer"><span class="dot"></span> Your pace. Real understanding.</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumbs"><button class="icon-btn mobile-toggle" type="button" data-action="toggle-nav" aria-label="Buka navigasi" aria-expanded="false">${icon('menu')}</button><span>Your workspace</span><span>/</span><strong>${esc(pageNames[route.page]||'Today')}</strong></div><div class="top-actions"><span id="save-status" class="save-status">${esc(ui.saveStatus||'Progres disimpan di perangkat ini')}</span><button class="icon-btn" type="button" data-action="theme" aria-label="Ubah tema">${icon('sun')}</button><a class="avatar" href="#settings" aria-label="Pengaturan profil">${esc((state.settings.name||'R').slice(0,2).toUpperCase())}</a></div></header><main id="main" class="main" tabindex="-1">${ui.storageWarning?`<div class="banner error" role="alert">${esc(ui.storageWarning)} ${btn('Export backup','#settings','small secondary')}</div>`:''}${renderPage(route,{state,catalog,ui})}</main></div>`;
}
function renderPage(route,ctx){if(route.page==='today')return today(ctx);if(route.page==='roadmap')return roadmap(ctx,route.query);if(route.page==='module')return modulePage(ctx,route.id);if(route.page==='learn')return lesson(ctx,route.id);if(route.page==='practice')return route.id?practiceView(ctx,route.id,route.query):practiceList(ctx,route.query);return extraView(route,ctx);}
function roadmap({state,catalog},query){const search=(query.get('search')||'').toLowerCase(),modules=catalog.modules.filter(m=>(m.title+' '+m.description+' '+m.stage).toLowerCase().includes(search)),groups=[...new Set(modules.map(m=>m.stage))];return `${title('The learning path','Dari nol, menuju pemahaman.','28 modul. Python dan C++. Fondasi dulu, kedalaman menyusul. Jelajahi materi dan gunakan prasyarat sebagai panduan.')}<form class="filter-bar" data-search="roadmap"><input type="search" name="search" placeholder="Cari topik: array, Python, graph…" aria-label="Cari modul" value="${esc(query.get('search')||'')}"><button class="btn secondary" type="submit">Cari modul</button></form><div class="banner">Jalur aktif: <strong>${state.settings.route==='interleaved'?'Python + C++ bertahap':'Berurutan'}</strong>. Ubah di <a href="#settings">Settings</a>. Python tetap dilatih selama bridge C++.</div>${groups.map((stage,i)=>`<div class="stage-header"><span class="stage-number">${String(i+1).padStart(2,'0')}</span><h2>${esc(stage)}</h2></div><div class="grid grid-3">${modules.filter(m=>m.stage===stage).map(m=>{const done=m.lessonIds.filter(id=>lessonDone(state,id)).length;return `<a class="module-card" href="#module/${m.id}"><div class="eyebrow">Module ${m.id.slice(1)} ${done===m.lessonIds.length?'· STUDIED':''}</div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="meta"><span>${m.lessonIds.length} pelajaran · ${m.exerciseIds.length} latihan</span><span>${done}/${m.lessonIds.length}</span></div><div class="progress-track"><span style="width:${done/m.lessonIds.length*100}%"></span></div></a>`;}).join('')}</div>`).join('')||empty('Tidak ada modul cocok.','Coba kata yang lebih umum.',btn('Reset pencarian','#roadmap','secondary'))}`;}
function modulePage({state,catalog},id){const m=catalog.modules.find(x=>x.id===id);if(!m)return empty('Modul tidak ditemukan.','Pilih modul dari learning path.',btn('Learning path','#roadmap'));return `${title(`Module ${m.id.slice(1)} · ${m.stage}`,m.title,m.description)}<div class="grid grid-2"><section class="panel"><div class="panel-heading"><h2>Empat langkah belajar</h2>${badge(`${m.estimatedHours?.join('–')||'15–20'} jam`,'outline')}</div>${m.lessonIds.map((id,i)=>{const l=catalog.lessons.find(x=>x.id===id);return `<a class="lesson-row" href="#learn/${id}"><span class="row-number">${lessonDone(state,id)?icon('check'):i+1}</span><div class="row-text"><h3>${esc(l?.title||id)}</h3><p>${l?.minutes||20} menit · ${lessonDone(state,id)?'Sudah dipelajari':'Lesson + checkpoint'}</p></div>${icon('arrow')}</a>`;}).join('')}<div class="footer-note">${(m.prerequisitesByRoute?.[state.settings.route]||m.prerequisites||[]).length?'Prasyarat yang disarankan: '+(m.prerequisitesByRoute?.[state.settings.route]||m.prerequisites||[]).map(x=>`<a href="#module/${esc(x)}">${esc(x.toUpperCase())}</a>`).join(', '):'Tidak memerlukan pengalaman programming sebelumnya.'}</div></section><section><div class="panel-heading"><h2>Latihan penerapan</h2><span class="muted" style="font-size:12px">${m.exerciseIds.length} aktivitas</span></div>${m.exerciseIds.map(id=>exerciseCard(catalog.exercises.find(x=>x.id===id),state)).join('')}</section></div>`;}
function lesson({state,catalog},id){const l=catalog.lessons.find(x=>x.id===id);if(!l)return empty('Pelajaran tidak ditemukan.','Kembali ke learning path.',btn('Learning path','#roadmap'));const m=catalog.modules.find(x=>x.id===l.moduleId),next=orderedLessons(state,catalog)[orderedLessons(state,catalog).findIndex(x=>x.id===l.id)+1],cp=l.checkpoint;return `${title(`Module ${l.moduleId.slice(1)} · ${l.minutes} min`,l.title,'Baca, prediksi, lalu coba. Menandai pelajaran selesai tidak otomatis berarti menguasai.')}<div class="lesson-layout"><article class="reading"><div class="objectives"><h3>Setelah pelajaran ini, kamu bisa…</h3><ul>${l.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></div>${l.blocks.map(b=>b.type==='code'?codeBlock(b.code,b.language):b.type==='callout'?`<aside class="callout"><h3>${esc(b.title||'Perhatikan')}</h3><p>${esc(b.body)}</p></aside>`:`<section>${b.title?`<h2>${esc(b.title)}</h2>`:''}<p>${esc(b.body)}</p></section>`).join('')}<form class="checkpoint" data-form="checkpoint" data-id="${l.id}"><div class="eyebrow">Check your understanding</div><h3>${esc(cp.question)}</h3>${cp.options.map((o,i)=>`<label class="choice"><input type="radio" name="answer" value="${i}" required><span>${esc(o)}</span></label>`).join('')}<div class="btn-row section-gap"><button class="btn" type="submit">Periksa pemahaman</button>${state.checkpointScores[l.id]===1?badge('Checkpoint passed','green'):''}</div><div id="checkpoint-feedback" class="section-gap" role="status"></div></form><div class="panel"><h3>Rangkum dengan kata-katamu</h3><ul>${l.summary.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><label class="choice"><input type="checkbox" id="lesson-reflection" ${state.reflections?.[l.id]?'checked':''}><span>Saya sudah mencoba menjelaskan kembali tanpa membaca.</span></label><button class="btn" data-action="complete-lesson" data-id="${l.id}" type="button">${lessonDone(state,l.id)?'Sudah dipelajari ✓':'Tandai dipelajari'}</button></div><div class="section-title"><h2>Coba terapkan</h2></div>${l.exerciseIds.map(eid=>catalog.exercises.find(e=>e.id===eid)).filter(Boolean).map(e=>exerciseCard(e,state)).join('')||'<p class="muted">Latihan terkait ada di halaman modul.</p>'}${sourceLinks(l.sources)}<div class="footer-note">Content v${l.version} · ${esc(l.id)} · Materi orisinal; sumber untuk pendalaman.</div><div class="btn-row section-gap">${btn('Kembali ke modul',`#module/${m.id}`,'secondary')}${next?btn('Pelajaran berikutnya',`#learn/${next.id}`):btn('Mulai review','#review')}</div></article><aside class="lesson-side"><div class="panel"><h3>Dalam modul ini</h3>${m.lessonIds.map((eid,i)=>{const item=catalog.lessons.find(x=>x.id===eid);return `<a class="lesson-row" href="#learn/${eid}" ${id===eid?'aria-current="page"':''}><span class="row-number">${lessonDone(state,eid)?'✓':i+1}</span><h3 class="row-title">${esc(item.title)}</h3></a>`;}).join('')}<div class="footer-note">${btn('Algorithm studio','#visualizers','secondary small')}</div></div></aside></div>`;}
